<script setup lang="ts">
import {computed,ref} from 'vue'
import {BriefcaseBusiness,Clock3,Coins,UserRound,GraduationCap,Handshake,Check,ArrowRight,Send,CheckCheck} from '@lucide/vue'
import type {ApiResult,Player,RoomState,Project,ContractStep} from '../types'
import content from '../content.json'
const props=defineProps<{player:Player;state:RoomState;busy:boolean;now:number;perform:(action:string,payload?:Record<string,unknown>)=>Promise<ApiResult|undefined>}>()
const modes=ref<Record<number,string>>({}),students=ref<Record<number,string>>({}),shares=ref<Record<number,number>>({})
const partner=computed(()=>Object.values(props.state.players).find(p=>p.id!==props.player.id))
function priority(pr:Project){return Number(pr.contract?.steps.some(st=>st.status==='invited'&&st.job?.partnerId===props.player.id))}
const projects=computed(()=>Object.values(props.state.projects).filter(pr=>pr.contract&&(pr.owner===props.player.id||pr.contract.steps.some(st=>st.job?.partnerId===props.player.id))).sort((a,b)=>priority(b)-priority(a)))
const icons={self:UserRound,student:GraduationCap,outsource:Coins,coop:Handshake}
const phaseNames={available:'待安排',invited:'等待搭子回复',working:'执行中',ready:'待验收',done:'已验收'}
const current=(pr:Project)=>pr.contract?.steps.find(st=>st.status!=='done')
const mode=(pr:Project)=>modes.value[pr.def]||'self'
const share=(pr:Project)=>shares.value[pr.def]||30
const quote=(pr:Project,id:string)=>pr.contract?.quotes?.[id]
const completed=(pr:Project)=>pr.contract?.steps.filter(st=>st.status==='done').length||0
const money=(n:number|undefined)=>Math.floor(n||0).toLocaleString()
function duration(ms:number|undefined){const min=Math.max(0,Math.ceil((ms||0)/60000));return min>=60?Math.floor(min/60)+' 小时'+(min%60?' '+min%60+' 分钟':''):min+' 分钟'}
function canAssign(pr:Project){const q=quote(pr,mode(pr));return !props.busy&&!!q&&props.player.funds>=q.cost&&(!(mode(pr)==='self'||mode(pr)==='coop')||!props.player.contractWork)&&(mode(pr)!=='student'||!!students.value[pr.def])&&(mode(pr)!=='coop'||!!partner.value)}
function studentUnavailable(st:Player['students'][number]){return!!st.contractWork||st.wellbeing<35||!!st.task&&['conference','visit'].includes(st.task.type)&&st.task.status!=='completed'}
async function start(pr:Project,step:ContractStep){await props.perform('contract_start',{project:pr.def,stageId:step.id,mode:mode(pr),studentId:students.value[pr.def],share:share(pr)})}
function progress(st:ContractStep){const job=st.job;if(!job?.duration||!job.dueAt)return 0;return Math.max(0,Math.min(100,(job.duration-(job.dueAt-props.now))/job.duration*100))}
</script>
<template>
 <div class="contract-intro"><BriefcaseBusiness :size="26"/><div><h2>横向要做事，经费才会到账。</h2><p>四个阶段，安排一次，离线等几小时；完成后提交验收。每阶段只需几次点击。</p></div></div>
 <div v-if="!projects.length" class="empty-state"><BriefcaseBusiness :size="34"/><h3>还没有横向合同</h3><p>去项目格签一份合同，或等搭子发来合作邀请。</p></div>
 <article v-for="pr in projects" :key="pr.def" class="contract-project"><header><span class="contract-owner" :class="state.players[pr.owner]?.discipline==='air'?'yizi':'fafa'">{{ state.players[pr.owner]?.profile.name }} 承接</span><span>{{ completed(pr) }} / {{ pr.contract!.steps.length }} 阶段验收</span><h2>{{ content.projects[pr.def]?.name }}</h2></header><div class="contract-ledger"><span>合同总额<b>{{ money(pr.finance?.totalFunding) }}</b></span><span>承接人到账<b>{{ money(pr.finance?.receivedFunding) }}</b></span><span>执行支出<b>{{ money(pr.finance?.workCosts) }}</b></span><span>搭子分账<b>{{ money(pr.finance?.partnerPaid) }}</b></span></div>
  <ol class="contract-stage-track"><li v-for="(st,i) in pr.contract!.steps" :key="st.id" :class="[st.status,{current:current(pr)?.id===st.id}]"><i><Check v-if="st.status==='done'" :size="12"/><template v-else>{{ i+1 }}</template></i><span>{{ st.title }}<small>{{ money(st.payment) }} 经费 · {{ phaseNames[st.status] }}</small></span></li></ol>
  <template v-for="st in current(pr)?[current(pr)!]:[]" :key="st.id"><section class="contract-current"><div class="contract-current-title"><span class="small-label">本阶段 · {{ phaseNames[st.status] }}</span><h3>{{ st.title }}</h3><b><Coins :size="17"/>{{ st.payment }} 经费</b></div>
   <form v-if="st.status==='available'&&pr.owner===player.id" @submit.prevent="start(pr,st)"><div class="execution-options"><button v-for="m in content.contracts.modes" :key="m.id" type="button" :class="{selected:mode(pr)===m.id}" :aria-pressed="mode(pr)===m.id" @click="modes[pr.def]=m.id"><component :is="icons[m.id as keyof typeof icons]" :size="18"/><strong>{{ m.name }}</strong><span>{{ duration(quote(pr,m.id)?.duration) }} · 支出 {{ quote(pr,m.id)?.cost||0 }}</span></button></div>
    <p class="contract-mode-note">{{ content.contracts.modes.find(m=>m.id===mode(pr))?.description }}</p><label v-if="mode(pr)==='student'">安排哪位同学<select v-model="students[pr.def]" required><option value="" disabled>选择本组在读学生</option><option v-for="st in player.students.filter(x=>!x.graduatedAt)" :key="st.id" :value="st.id" :disabled="studentUnavailable(st)">{{ st.name }} · 心情 {{ st.wellbeing }}{{ studentUnavailable(st)?' · 暂不可安排':'' }}</option></select></label><template v-if="mode(pr)==='coop'"><label>给 {{ partner?.profile.name||'搭子' }} 的阶段分账<select :value="share(pr)" @change="shares[pr.def]=Number(($event.target as HTMLSelectElement).value)"><option v-for="n in [10,20,30,40,50]" :key="n" :value="n">{{ n }}% · {{ Math.floor(st.payment*n/100) }} 经费</option></select></label><p class="contract-coop-note">发出邀请不扣费。{{ partner?.profile.name||'搭子' }} 接受后才开工，完成后 TA 收到 {{ Math.floor(st.payment*share(pr)/100) }}，你收到 {{ st.payment-Math.floor(st.payment*share(pr)/100) }} 经费。</p></template>
    <div class="contract-start-summary"><span>开工支出 <b>{{ quote(pr,mode(pr))?.cost||0 }}</b> · 验收拨款 <b>{{ st.payment }}</b><small>装备、专业与成果加成用于缩短工期。</small></span><button class="primary" :disabled="!canAssign(pr)"><component :is="mode(pr)==='coop'?Send:ArrowRight" :size="15"/>{{ mode(pr)==='coop'?'发出合作邀请':'安排本阶段' }}</button></div><p v-if="(mode(pr)==='self'||mode(pr)==='coop')&&player.contractWork" class="contract-busy-note">你的横向工作位正忙，可以改用学生、经费外协，或完成当前工作后再来。</p>
   </form>
   <div v-else-if="st.status==='invited'" class="contract-invitation"><Handshake :size="29"/><h3>{{ pr.owner===player.id?'正在等 '+state.players[st.job!.partnerId!]?.profile.name+' 回复':state.players[pr.owner]?.profile.name+' 邀请你一起做横向' }}</h3><p>预计合作 {{ duration(st.job?.quote?.duration) }}；承接人承担 {{ st.job?.quote?.cost }} 材料费。验收后搭子分得 {{ Math.floor(st.payment*(st.job?.share||0)/100) }} 经费（{{ st.job?.share }}%）。</p><p>{{ duration((st.job?.expiresAt||now)-now) }}内可回复，不要求同时在线。</p><div v-if="st.job?.partnerId===player.id"><button class="primary" :disabled="busy||!!player.contractWork||!!state.players[pr.owner]?.contractWork" @click="perform('contract_respond',{project:pr.def,stageId:st.id,accept:true})"><Handshake :size="15"/>接受，一起做</button><button class="secondary" :disabled="busy" @click="perform('contract_respond',{project:pr.def,stageId:st.id,accept:false})">这次先不了</button><small v-if="player.contractWork||state.players[pr.owner]?.contractWork">有一方的横向工作位正忙，空闲后才能开工。</small></div><button v-else class="secondary" :disabled="busy" @click="perform('contract_cancel',{project:pr.def,stageId:st.id})">撤回，换一种方式</button></div>
   <div v-else-if="st.status==='working'" class="contract-working"><span><Clock3 :size="20"/>{{ (st.job?.dueAt||0)>now?duration(st.job!.dueAt!-now)+'后可验收':'正在同步完成状态…' }}</span><div class="progress-track"><i :style="{width:progress(st)+'%'}"/></div><p>{{ content.contracts.modes.find(m=>m.id===st.job?.mode)?.name }}{{ st.job?.studentName?' · '+st.job.studentName:'' }} · 已支出 {{ st.job?.cost }} 经费</p><p v-if="state.effects.some(e=>e.type==='pause'&&e.project===pr.def&&e.expires>now)">园区停电中，工作时钟暂停，预计完成时间已顺延。</p><p v-if="st.job?.mode==='student'">同学的个人研究在占用期间减速，完成后恢复；记得听听 TA 的近况。</p><p v-if="st.job?.mode==='coop'">分账已约定：{{ state.players[st.job.partnerId!]?.profile.name }} {{ st.job.share }}%。完成后任一参与者都可以提交验收。</p></div>
   <div v-else-if="st.status==='ready'" class="contract-ready"><CheckCheck :size="29"/><h3>事情做完了，交给甲方验收吧。</h3><p>提交后按约定拨付 {{ st.payment }} 经费，重复点击不会再次发钱。</p><button v-if="st.job?.participants.includes(player.id)" class="primary" :disabled="busy" @click="perform('contract_claim',{project:pr.def,stageId:st.id})">提交验收并收款<ArrowRight :size="15"/></button><p v-else>等待本阶段的参与者提交验收。</p></div>
  </section></template>
  <div v-if="!current(pr)" class="contract-completed"><CheckCheck :size="19"/>合同已完成，所有阶段款均已按约定分配。</div><section v-if="pr.contract!.steps.some(st=>st.status==='done')" class="contract-payment-history"><h3>已验收与分账</h3><div v-for="st in pr.contract!.steps.filter(st=>st.status==='done')" :key="st.id"><span>{{ st.title }}</span><b v-for="pay in st.payouts" :key="pay.id" :class="state.players[pay.id]?.discipline==='air'?'yizi':'fafa'">{{ pay.name }} +{{ pay.amount }}</b></div></section>
 </article>
</template>
